{%- set nodes = [('whitey','Whitey'),('larry','Larry'),('lumpy','Lumpy'),('uther','Uther')] %}
{%- set ns = namespace(alerts=[]) %}
{%- for h, label in nodes %}
{%- set e = 'sensor.' ~ h ~ '_metrics' %}
{%- if states(e) != 'online' %}
{%- set ns.alerts = ns.alerts + ['**' ~ label ~ ' unreachable**'] %}
{%- else %}
{%- if state_attr(e,'reboot_required') %}
{%- set ns.alerts = ns.alerts + [label ~ ' needs reboot'] %}
{%- endif %}
{%- if not state_attr(e,'raid_ok') %}
{%- set ns.alerts = ns.alerts + ['**' ~ label ~ ' RAID degraded**'] %}
{%- endif %}
{%- set u = state_attr(e,'updates') | int(0) %}
{%- if u > 0 %}
{%- set ns.alerts = ns.alerts + [label ~ ': ' ~ u ~ ' updates'] %}
{%- endif %}
{%- for f in state_attr(e,'filesystems') or [] %}
{%- if f.pct | float(0) > 85 %}
{%- set ns.alerts = ns.alerts + ['**' ~ label ~ ' ' ~ f.mount ~ ' at ' ~ f.pct ~ '%**'] %}
{%- endif %}
{%- endfor %}
{%- for c in state_attr(e,'docker') or [] %}
{%- if c.state != 'running' %}
{%- set ns.alerts = ns.alerts + ['**' ~ label ~ ': ' ~ c.name ~ ' ' ~ c.state ~ '**'] %}
{%- endif %}
{%- endfor %}
{%- for s in state_attr(e,'units') or [] %}
{%- if s.state not in ['active','unknown'] %}
{%- set ns.alerts = ns.alerts + ['**' ~ label ~ ': ' ~ s.unit ~ ' ' ~ s.state ~ '**'] %}
{%- endif %}
{%- endfor %}
{%- endif %}
{%- endfor %}
{%- set b = states('sensor.oldest_backup_age') | int(-1) %}
{%- if b > 30 %}
{%- set ns.alerts = ns.alerts + ['**Backup stale: ' ~ b ~ 'h**'] %}
{%- endif %}
{%- if ns.alerts %}
## Attention
{% for a in ns.alerts %}- {{ a }}
{% endfor %}
{%- else %}
## All systems nominal
Four nodes online, backups current, no pending updates.
{%- endif %}

{% set wan = states("binary_sensor.media_room_gilbert_internet") %}
{% set nodes = [
  ["Media room (main)", "binary_sensor.media_room_gilbert_aimesh_zenwifi_ax_04_42_1a_c8_13_b0"],
  ["Shop (node 2)", "binary_sensor.shop_gilbert_node_2_aimesh_zenwifi_ax_7c_10_c9_06_16_80"],
  ["Krizzy office (node 3)", "binary_sensor.krizzy_s_office_gilbert_node_3_aimesh_zenwifi_ax_7c_10_c9_06_29_00"] ] %}
{% set ns = namespace(up=0) %}
{% for label, ent in nodes %}{% if states(ent) == "on" %}{% set ns.up = ns.up + 1 %}{% endif %}{% endfor %}
{% set clients = states("sensor.media_room_gilbert_connected_devices") %}
{% set fw = states("update.media_room_gilbert_firmware_update") %}
{% set fw_now = state_attr("update.media_room_gilbert_firmware_update", "installed_version") %}
{% set fw_new = state_attr("update.media_room_gilbert_firmware_update", "latest_version") %}
{% if wan == "on" %}**Internet up** - gilbert reports the WAN link is connected
{% elif wan == "off" %}**INTERNET DOWN** - gilbert reports no WAN connection
{% else %}**Router unreachable** - cannot tell whether the internet is up
{% endif %}

| Check | Value |
|---|---|
| WAN link | {% if wan == "on" %}connected ✅{% elif wan == "off" %}DISCONNECTED ❌{% else %}unknown ({{ wan }}) ⚠️{% endif %} |
| Clients | {% if clients not in ["unavailable","unknown"] %}{{ clients }} connected{% else %}not reporting{% endif %} |
| Router firmware | {{ fw_now if fw_now else "unknown" }}{% if fw == "off" %} ✅{% endif %} |

**AiMesh nodes** - {{ ns.up }} of {{ nodes | count }} up

| Node | State |
|---|---|
{% for label, ent in nodes %}| {{ label }} | {% if states(ent) == "on" %}connected ✅{% elif states(ent) == "off" %}DOWN ❌{% else %}not reporting ⚠️{% endif %} |
{% endfor %}
{%- if wan not in ["on","off"] %}

**Home Assistant cannot reach gilbert.** This is not the same as an internet
outage - the router itself may be down, rebooting, or unreachable on the LAN.
{% endif %}
{%- if fw == "on" %}

**Firmware update reported: {{ fw_new }}** - confirm it is a Gnuton build
before acting. Never use the Install button: it calls the stock ASUS upgrade
path, which is wrong for Gnuton. Flash manually. See runbook section 4c.
{% endif %}
{%- if ns.up < nodes | count and wan == "on" %}
{% set missing = nodes | count - ns.up -%}
**AiMesh degraded** - {{ missing }} {{ "node is" if missing == 1 else "nodes are" }} not reporting. WiFi coverage may be reduced even though the internet is fine.
{%- endif %}

{% set rs = (state_attr("sensor.lumpy_metrics","extra") or {}).get("rsnapshot") %}
  {% if rs is none %}
  No rsnapshot state reported. Check the ha-rsnapshot-state timer on lumpy.
  {% else %}
  {% set bad = (not rs.mounted) or rs.stalled or rs.root_local or (rs.no_create_root | int != 1) or (rs.lock_present and not rs.lock_alive) or (rs.log_errors | int > 0) or (rs.last_run_rc | int > 0) or (not rs.list_ok) %}
  **{% if bad %}Problem{% else %}Healthy{% endif %}**{% if rs.lock_alive %} - backup running now{% endif %}

  | Level | Snapshots | Newest |
  |---|:---:|---:|
  {% for l in rs.levels %}| {{ l.level }} | {{ l.count }} / {{ l.retain }} | {% if l.age_hours | int < 0 %}unknown{% elif l.age_hours | int > 72 %}{{ l.age_hours | int // 24 }} d{% else %}{{ l.age_hours }} h{% endif %} |
  {% endfor %}

  {{ rs.fstype }} {{ rs.source }}

  Volume {{ rs.disk_pct }}% used, {{ (rs.disk_free_bytes | int / 1024**4) | round(1) }} TB free

  Errors since last success: {{ rs.log_errors }}
  {% if not rs.mounted or rs.stalled %}

  **ALERT: snapshot root unreachable**
  {% endif %}
  {% if rs.root_local %}

  **ALERT: snapshot root is on local disk, NFS absent**
  {% endif %}
  {% if rs.no_create_root | int != 1 %}

  **ALERT: no_create_root is 0, may fill lumpy root fs**
  {% endif %}
  {% if rs.lock_present and not rs.lock_alive %}

  **ALERT: stale lockfile, future runs blocked**
  {% endif %}
  {% if rs.last_run_rc | int > 0 %}

  **ALERT: last run exited {{ rs.last_run_rc }}**
  {% endif %}
  {% if rs.last_run_rc | int >= 0 %}

  Last run: {{ rs.last_run_level }}, exit {{ rs.last_run_rc }}, {{ (rs.last_run_seconds | int / 60) | round(0) | int }} min, {{ rs.last_run_age_hours }}h ago
  {% endif %}
  {% endif %}

{% set v = (state_attr("sensor.uther_metrics","extra") or {}).get("vpn") %}
  {% if v is none %}
  No VPN state reported. Check the ha-vpn-state timer on uther.
  {% else %}
  {% set age = (as_timestamp(now()) - (v.ts | int(0))) | int %}
  {% set st = "stale" if age > 900 else v.status %}
  {% if st == "stale" %}**State is {{ (age / 60) | int }} min old** - not trustworthy
  {% elif st == "ok" %}**Tunneled** - egress confirmed via PIA
  {% elif st == "ok_unconfirmed" %}**Tunnel up** - egress not confirmed yet
  {% elif st == "leak" %}**LEAK** - traffic is using the ISP address
  {% elif st == "leak_route" %}**LEAK RISK** - bypass route present in namespace
  {% elif st == "blocked" %}**Blocked** - no route in namespace, torrents stalled
  {% elif st == "namespace_missing" %}**Namespace missing** - vpn-netns is down
  {% elif st == "tunnel_missing" %}**Tunnel missing** - wg-quick pia is down
  {% elif st == "orphaned" %}**Stale namespace** - restart qbittorrent-nox
  {% elif st == "tunnel_stale" %}**No handshake** in over 5 minutes
  {% elif st == "wan_down" %}**Internet down** - VPN state unknown
  {% else %}**Unknown state** {{ st }}
  {% endif %}

  | Check | Value |
  |---|---|
  | Egress via VPN | {% if v.egress_ip_vpn %}{{ v.egress_ip_vpn }}{% else %}unknown{% endif %} |
  | Egress via WAN | {% if v.egress_ip_wan %}{{ v.egress_ip_wan }}{% else %}unknown{% endif %} |
  | Handshake | {% if v.handshake_age_s | int < 0 %}none{% else %}{{ v.handshake_age_s }} s ago{% endif %} |
  | Default route | {% if v.default_route_dev == "pia" %}✅ pia{% elif v.default_route_dev %}❌ {{ v.default_route_dev }}{% else %}❌ none{% endif %} |
  | Transferred | {{ (v.rx_bytes | int / 1024**3) | round(1) }} GiB in, {{ (v.tx_bytes | int / 1024**3) | round(1) }} GiB out |
  | qBittorrent | {% if v.qbit_running %}{% if v.qbit_ns_ok | int == 1 %}running, namespace ok{% else %}running, WRONG namespace{% endif %}{% else %}not running{% endif %} |
  | Internet | {% if v.wan_up %}up{% else %}DOWN{% endif %}, DNS {% if v.dns_ok %}ok{% else %}FAILING{% endif %} |
  {% if v.leak_route_present %}

  **ALERT: a default route via the veth exists - traffic can bypass PIA**
  {% endif %}
  {% if age > 900 %}

  **ALERT: state is {{ (age / 60) | int }} min old - ha-vpn-state timer may be dead**
  {% endif %}
  {% endif %}

